        _key = (table.display_name or key.as_string())
        if prefix is not None:
            _key = prefix + "." + _key
        cur += f"{table.trivia.indent}{open_}{_key}{close}{table.trivia.comment_ws}{table.trivia.trail}\n"
    for k, v in iter_body(table.value, sort_keys):
